// from 2015 that have the most comments
db.movies.aggregate([
  { $match: { year: 2015 } },
  { $sort: { num_mflix_comments: -1 } },
  { $limit: 10 },
  { $project: { _id: 0, genres: 1, runtime: 1 } }
]);
